# Your solution code here
def solution(input_string):
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    # Since a - b <= 10^6, we can use Dijkstra's algorithm on the range [b, a]
    dist = {}

    # Queue for Dijkstra: (current_value, moves)
    import heapq
    pq = [(0, a)]

    dist[a] = 0

    while pq:
        moves, curr = heapq.heappop(pq)

        if curr == b:
            return str(moves)

        # Already visited with better or equal moves
        if curr in dist and dist[curr] <= moves:
            continue

        # Operation 1: subtract 1
        if curr - 1 >= b:
            new_moves = moves + 1
            if curr - 1 not in dist or new_moves < dist[curr - 1]:
                dist[curr - 1] = new_moves
                heapq.heappush(pq, (new_moves, curr - 1))

        # Operation 2: subtract (curr mod xi) for each xi
        for xi in x:
            rem = curr % xi
            if rem > 0:
                target = curr - rem
                if target >= b:
                    new_moves = moves + 1
                    if target not in dist or new_moves < dist[target]:
                        dist[target] = new_moves
                        heapq.heappush(pq, (new_moves, target))

    # If we can't reach b (shouldn't happen), return 0
    return str(dist[b] if b in dist else 0)

