                return None

            d = directions[row][col]
            rows, cols = row, col

            if d == 'U':
                rows -= 1
                cols = col
            elif d == 'D':
                rows += 1
                cols = col
            elif d == 'L':
                rows = row
                cols -= 1
            elif d == 'R':
                rows = row
                cols += 1

            return rows, cols

        def find_cycle_info(row, col):
            if (row, col) in dist_to_cycle_map:
                return dist_to_cycle_map[(row, col)]
            if (row, col) in cycle_id:
                # Already processed
                return cycle_id[(row, col)]

            cache = {}

            def follow(row, col):
                if (row, col) in cache:
                    return False, cache[(row, col)]

                if (row, col) in cycle_id:
                    return True, cycle_id[(row, col)]

                if (row, col) in dist_to_cycle_map:
                    return True, dist_to_cycle_map[(row, col)]

                cache[(row, col)] = None
                next_row, next_col = get_targets_cell(row, col)

                d, cycle = follow(next_row, next_col)

                cache[(row, col)] = d
                return d, cycle

            d, cycle = follow(row, col)
            return cycle, d

        # Compute for all cells
        count = 0
        black = 0

        for i in range(n):
            for j in range(m):
                d, c = find_cycle_info(i, j)
                if d is not None:
                    if d == 0:
                        count += 1
                        if grid[i][j] == '0':
                            black += 1

        results.append(f"{count} {black}")

    return '\n'.join(results)

