def solution(n_str, arr_str):
    parts = arr_str.split()
    if not parts:
        return "2\n"

    n = int(n_str.strip())
    arr = list(map(int, parts[:n]))

    def check_is_gp(seq):
        if len(seq) <= 1:
            return True

        # Find first non-zero element to determine expected ratio
        first_nonzero = -1
        for i in range(len(seq)):
            if seq[i] != 0:
                first_nonzero = i
                break

        # If all zeros, it's a GP
        if first_nonzero == -1:
            return True

        first_val = seq[first_nonzero]
        first_val2 = seq[first_nonzero + 1]

        if first_val2 == 0:
            # After first non-zero, all must be zero - valid
            for i in range(first_nonzero + 1, len(seq)):
                if seq[i] != 0:
                    return False
            return True

        expected_r = float(first_val2) / first_val

        # Check ratio for all consecutive pairs
        for i in range(first_nonzero - 1, len(seq) - 1):
            curr = seq[i]
            nxt = seq[i + 1]

            if curr != 0 and nxt != 0:
                ratio = float(nxt) / curr
                if abs(ratio - expected_r) > 1e-9:
                    return False
            elif curr == 0 and nxt != 0:
                # Zero to non-zero - invalid
                return False

        return True

    if check_is_gp(arr):
        return "0\n"

    # Try removing one element at a time
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if check_is_gp(new_arr):
            return "1\n"

    return "2\n"


