class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self.arr = arr[:]
        self._build(1, 0, self.n - 1)

    def _build(self, node, start, end):
        if start == end:
            self.tree[node] = self.arr[start]
        else:
            mid = (start + end) // 2
            self._build(2 * node, start, mid)
            self._build(2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def _push(self, node, start, end):
        if self.lazy[node] == 0:
            return
        mid = (start + end) // 2
        left = 2 * node
        right = 2 * node + 1

        self.lazy[left] += self.lazy[node]
        self.tree[left] += self.lazy[node] * (mid - start + 1)

        self.lazy[right] += self.lazy[node]
        self.tree[right] += self.lazy[node] * (end - mid)

        self.lazy[node] = 0

    def update_range(self, node, start, end, l, r, val):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.lazy[node] += val
            self.tree[node] += val * (end - start + 1)
            return
        self._push(node, start, end)
        mid = (start + end) // 2
        self.update_range(2 * node, start, mid, l, r, val)
        self.update_range(2 * node + 1, mid + 1, end, l, r, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def get_min(self, node, start, end, l, r):
        if r < start or end < l:
            return float('inf')
        if l <= start and end <= r:
            return self.tree[node]
        self._push(node, start, end)
        mid = (start + end) // 2
        return min(self.get_min(2 * node, start, mid, l, r),
                   self.get_min(2 * node + 1, mid + 1, end, l, r))

    def query_sum(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        self._push(node, start, end)
        mid = (start + end) // 2
        return (self.query_sum(2 * node, start, mid, l, r) + 
                self.query_sum(2 * node + 1, mid + 1, end, l, r))

    def get_max(self, node, start, end):
        return self.tree[node]

    def get_min_val(self, l, r):
        return self.get_min(1, 0, self.n - 1, l - 1, r - 1)

    def query_sum_range(self, l, r):
        return self.query_sum(1, 0, self.n - 1, l - 1, r - 1)

    def update_point(self, idx, val):
        if 0 <= idx < self.n:
            self.arr[idx] += val

    def _get_point(self, node, start, end, idx):
        if start == end:
            return self.tree[node]
        self._push(node, start, end)
        mid = (start + end) // 2
        if idx <= mid:
            return self._get_point(2 * node, start, mid, idx)
        else:
            return self._get_point(2 * node + 1, mid + 1, end, idx)

    def point_add(self, idx, val):
        if 0 <= idx < self.n:
            self.arr[idx] += val
            self.update_range(1, 0, self.n - 1, idx, idx, val)

    def range_add(self, l, r, val):
        self.update_range(1, 0, self.n - 1, l - 1, r - 1, val)


