def solution(input_str):
    lines = input_str.strip().split('\n')

    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])

    actions = []
    for i in range(3, 3 + m):
        action, team = lines[i].split()
        actions.append((action, int(team)))

    # Sort heroes by strength in descending order for efficiency
    sorted_strengths = sorted(set(strengths), reverse=True)

    # Create strength to count mapping to handle duplicates
    from collections import Counter
    strength_counts = Counter(strengths)

    @lru_cache(None)
    def dp(action_idx, strength_set, t1, t2):
        if action_idx == m:
            return t1 - t2

        action_type, team = actions[action_idx]

        if action_type == 'p':  # pick
            if team == 1:
                # Team 1 will maximize the result
                max_diff = -float('inf')
                for s in list(strength_set):
                    # Find all heroes with strength s that are available
                    count_in_set = sum(1 for x in strength_set if x == s)
                    # Only pick if there's at least one instance available
                    if count_in_set >= 1:
                        # Pick one instance
                        new_set = strength_set - {s}
                        new_t1 = t1 + s
                        val = dp(action_idx + 1, new_set, new_t1, t2)
                        max_diff = max(max_diff, val)
                return max_diff
            else:
                # Team 2 will minimize the result
                min_diff = float('inf')
                for s in list(strength_set):
                    count_in_set = sum(1 for x in strength_set if x == s)
                    if count_in_set >= 1:
                        new_set = strength_set - {s}
                        new_t2 = t2 + s
                        val = dp(action_idx + 1, new_set, t1, new_t2)
                        min_diff = min(min_diff, val)
                return min_diff
        else:  # ban
            if team == 1:
                # Team 1 will ban to maximize their outcome
                max_diff = -float('inf')
                for s in strength_set:
                    new_set = strength_set - {s}
                    val = dp(action_idx + 1, new_set, t1, t2)
                    max_diff = max(max_diff, val)
                return max_diff
            else:
                # Team 2 will ban to minimize team 1's outcome
                min_diff = float('inf')
                for s in strength_set:
                    new_set = strength_set - {s}
                    val = dp(action_idx + 1, new_set, t1, t2)
                    min_diff = min(min_diff, val)
                return min_diff

    # Initial set of all hero strengths (as a frozenset to make it hashable)
    result = dp(0, frozenset(sorted_strengths), 0, 0)
    return str(result)

