                if x == 0:
                    # Just middle
                    total_len = middle_len
                    if total_len > best_len:
                        best_len = total_len
                        best_result = [(start, middle_len)]
                else:
                    # Try to find prefix of length x
                    if start >= x:
                        prefix = s[start-x:start]
                        suffix_end = end + x
                        if suffix_end <= n:
                            suffix = s[suffix_end:suffix_end+x]

                            # For palindrome, prefix must be reverse of suffix
                            if prefix == suffix[::-1]:
                                total_len = x + middle_len + x
                                if total_len > best_len:
                                    best_len = total_len
                                    best_result = [
                                        (start - x, x), 
                                        (start, middle_len), 
                                        (end + x, x)
                                    ]
                        else:
                            # Not enough suffix - check within boundaries
                            available_suffix = n - end
