    # Ensure l >= 2 since primes start from 2
    start_l = max(2, l)

    if start_l > r:
        return '0\n'

    # Create sieve for range [start_l, r]
    # Use bytearray for memory efficiency
    size = r - start_l + 1
    is_prime_local = bytearray([1]) * size
    is_prime_local[0] = 0  # start_l might not be prime anyway

    if start_l == 2:
        is_prime_local[0] = 1  # 2 is prime

    # Sieve up to sqrt(r)
    sqrt_r = int(r**0.5) + 1

    for i in range(2, sqrt_r):
        if i * i > r:
            break
        # Mark multiples of i in our local range
        # First multiple >= start_l
        first = ((start_l + i - 1) // i) * i
        if first < i * i:
            first = i * i

        for j in range(first, r + 1, i):
            idx = j - start_l
            is_prime_local[idx] = 0

    # Use sieve from 2 to sqrt(r) for base sieving
    base_limit = sqrt_r
    is_prime_base = bytearray([1]) * (base_limit + 1)
    if base_limit >= 0:
        is_prime_base[0] = 0
    if base_limit >= 1:
        is_prime_base[1] = 0

    for i in range(2, int(base_limit**0.5) + 1):
        if is_prime_base[i]:
            for j in range(i * i, base_limit + 1, i):
                is_prime_base[j] = 0

    # Now properly sieve our range
    if start_l <= 2:
        is_prime_local[0] = 1  # 2 is prime

    # Careful sieving from 2 to sqrt(r)
    base_limit = int(r**0.5) + 1

    for p in range(2, base_limit + 1):
        if (p * p > r):
            break

        # Find first multiple of p >= start_l
        first = p * p
        if first < start_l:
            first = ((start_l + p - 1) // p) * p

        # Mark multiples
        for j in range(first, r + 1, p):
            idx = j - start_l
            is_prime_local[idx] = 0

    # Count lucky numbers
    count = 0
    for i in range(start_l, r + 1):
        idx = i - start_l
        if is_prime_local[idx]:
