def solution(input_str):
    """
    Solves the hexagonal chocolate game using minimax with memoization.
    Returns "Karlsson" if first player wins, "Lillebror" otherwise.
    """
    lines = input_str.strip().split('\n')
    grid = []
    for line in lines:
        grid.append(line.strip().split())

    # Build adjacency in canonical form - each row i has 3 + i + (1 if i>2 else 0) cells
    # More precisely: R0:3, R1:4, R2:5, R3:4, R4:3
    n_rows = 5
    row_lengths = [3, 4, 5, 4, 3]

    # Directions for lines (all 6 directions in hexagonal grid)
    # Each direction is defined by (dr, dc_offset) where dc_offset is adjustment for staggered rows
    directions = [
        (1, 0),   # Down-left
        (1, 1),   # Down-right
        (0, 1),   # Right
        (-1, 1),  # Up-right
        (-1, 0),  # Up-left
        (0, -1),  # Left (won't work due to non-square)
    ]

    # Convert grid to a flat representation with (r, c) coordinates
    def in_bounds(r, c):
        return 0 <= r < n_rows and 0 <= c < row_lengths[r]

    def get_cell(r, c):
        return grid[r][c] if in_bounds(r, c) else '.'

    def is_chocolate(r, c):
        return get_cell(r, c) == 'O'

    # Generate all lines (contiguous in 6 directions) containing at least one chocolate
    lines = []

    for r in range(n_rows):
        for c in range(row_lengths[r]):
            if is_chocolate(r, c):
                # Try all 6 directions from each chocolate position
                seen_dirs = set()
                for dr, dc in directions:
                    if (r, c) in seen_dirs:
                        continue
                    seen_dirs.add((r, c))

                    # Trace line in both directions
                    path = []
                    i, j = r, c
                    while in_bounds(i, j) and is_chocolate(i, j):
                        path.append((i, j))
                        i += dr
                        j += dc

                    # Go backwards
                    path_rev = []
                    i, j = r, c
                    while in_bounds(i, j) and is_chocolate(i, j):
                        path_rev.append((i, j))
                        i -= dr
                        j -= dc

                    path = path + path_rev

                    if len(path) >= 2 and path:  # At least 2 chocolates for valid move
                        # Add as tuple
                        lines.append(tuple(path))

    # Remove duplicate lines
    unique_lines = []
    seen_lines = set()
    for line in lines:
        if line not in seen_lines:
            seen_lines.add(line)
            unique_lines.append(line)

    lines = unique_lines
    n_lines = len(lines)

    # Minimax with memoization
    memo = {}

    def get_chocolate_count(state):
        return sum(grid[r][c] == 'O' for r in range(n_rows) for c in range(row_lengths[r]))

    def get_possible_moves(state):
        moves = []
        for i in range(n_lines):
            if all(is_chocolate(r, c) for r, c in lines[i]):
                # Any non-empty subset of chocolates on this line as a move
                indices = [0, 1, 2, 3, 4, 5, 6, 7, 8]
                subset = []
                for mask in range(1, 1 << 9):
                    subset = []
                    for k in range(9):
                        if mask & (1 << k):
                            idx = lines[i][k]
                            if is_chocolate(idx[0], idx[1]):
                                subset.append(idx)
                    if subset:
                        moves.append(tuple(subset))
        return moves

    # Actually, the problem says "one or several chocolates that lay in the neighboring cells on one line"
    # This means any contiguous sequence on a line
    def get_moves_for_line(line):
        indices = [(r, c) for r, c in line]
        moves = []
        n = len(indices)
        for start in range(n):
            for end in range(start, n):
                moves.append(tuple(indices[start:end+1]))
        return moves

    # Represent game state as tuple of (r,c) coordinates of chocolates
    def state_tuple(chocolate_positions):
        return tuple(sorted(chocolate_positions))

    def solve(state):
        if not state:
            return False  # No move possible, losing position

        if state_tuple(state) == state:
            pass  # Already memoized key
        key = state

        if key in memo:
            return memo[key]

        # All possible moves
        moves = []
        for line in lines:
            line_chocs = [idx for idx in line if is_chocolate(idx[0], idx[1])]
            for start in range(len(line_chocs)):
                for end in range(start, len(line_chocs)):
                    indices = line_chocs[start:end+1]
                    next_state = set(state) - set(indices)
                    if next_state:
                        moves.append(next_state)

        # If first player can force a win from some move, they win
        for next_state in moves:
            if solve(next_state) == True:
                memo[key] = True
                return True

        memo[key] = False
        return False

    # Get initial chocolate positions
    choco_positions = []
    for r in range(n_rows):
        for c in range(row_lengths[r]):
            if is_chocolate(r, c):
                choco_positions.append((r, c))

    initial_state = state_tuple(choco_positions)

    # If first player has any winning move, Karlsson wins
    result = solve(initial_state)

    return "Karlsson" if result else "Lillebror"

