    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    def can_achieve(x):
        max_needed = 0
        for h, a in bamboos:
            base = h + a * m
            if base > x:
                needed = (base - x - 1) // p + 1
                max_needed = max(max_needed, needed)
        return max_needed <= k * m

    global_min = min(h for h, a in bamboos) if bamboos else 0
    global_max = max(h + a * m for h, a in bamboos) + 1
    if global_max <= k * p * m:
        global_max = min(global_max, k * p * m + 10**18)

    if global_max <= 1:
        return str(global_min + '\n')

    low = global_min
    high = global_max

    while low < high:
        mid = (low + high) // 2
        if can_achieve(mid):
            high = mid
        else:
            low = mid + 1

    return str(low + '\n')

