import math
import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return f"{0.0:.10f}\n"

    xp, yp, vp = map(int, lines[0].split())
    x, y, v, r = map(int, lines[1].split())

    R = math.sqrt(xp*xp + yp*yp)
    starting_angle = math.atan2(yp, xp)
    qwerty_start = (float(x), float(y))

    def get_persephone_pos(t):
        angle = starting_angle + (vp * t) / R
        return (R * math.cos(angle), R * math.sin(angle))

    def dist(p1, p2):
        return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

    def closest_point_on_segment(a, b, p):
        A = b[0] - a[0]
        B = b[1] - a[1]
        len_sq = A*A + B*B

        if len_sq == 0:
            return (a[0], a[1])

        u = ((p[0] - a[0]) * A + (p[1] - a[1]) * B) / len_sq
        u = max(0.0, min(1.0, u))
        return (a[0] + u * A, a[1] + u * B)

    def min_dist_to_origin(a, b):
        closest = closest_point_on_segment(a, b, (0.0, 0.0))
        return math.hypot(closest[0], closest[1])

    def check(t):
        if t < 0:
            return False

        p = get_persephone_pos(t)
        d = dist(qwerty_start, p)

        if d > v * t:
            return False

        min_distance = min_dist_to_origin(qwerty_start, p)
        if min_distance < r:
            return False

        return True

    # Check for immediate interception
    p0 = get_persephone_pos(0)
    d0 = dist(qwerty_start, p0)
    if d0 <= 1e-9:
        return f"{0.0:.10f}\n"

    # Binary search for minimum time
    low = 0.0
    high = 1000000.0  # Large enough upper bound

    for _ in range(100):
        mid = (low + high) / 2
        if check(mid):
            high = mid
        else:
            low = mid

    return f"{high:.10f}\n"

