    for x in arr:
        # When we have at least 2 elements in stack and top is smaller than current
        # we can remove the top element, getting min(left_neighbor, current_element) points
        while len(stack) >= 2 and stack[-1] <= x:
            mid = stack.pop()
            ans += min(stack[-1], x)
        stack.append(x)

    # Process remaining elements in stack (they are in non-decreasing order)
    # We need to account for how they contribute to the final score
    if len(stack) >= 2:
        stack.pop()
        if len(stack) >= 1:
            ans += min(stack[-1], stack[-1])  # The second element acts as right neighbor for first
        # Also need to consider the first element pairs with the original last element
        if len(stack) >= 1:
            ans += stack[-1]  # Each remaining element contributes its value

    # Add remaining elements from original array that weren't processed due to stack condition
    # This handles the case where elements form an increasing sequence
    remaining = [arr[-1]]
