    sorted_rows = []
    for i in range(n):
        for j in range(m):
            sorted_rows.append(A[i][j])
        sorted_rows.sort(reverse=True)

    # Place values along a bitonic path pattern
    # Start with the largest values at strategic positions
    sorted_all = sorted(range(1, n * m + 1), reverse=True)
    idx = 0

    # Fill diagonally from top-left, preferring increasing then decreasing
    size = min(n, m)
    for k in range(size):
        r = k
        c = k
        if result[r][c] == 0:
            result[r][c] = sorted_all[idx]
            used[sorted_all[idx]] = True
            idx += 1

        r2 = k
        c2 = m - k - 1
        if result[r2][c2] == 0:
            if sorted_all[idx] < sorted_all[idx - 1] if idx > 0 else True:
                result[r2][c2] = sorted_all[idx]
                used[sorted_all[idx]] = True
                idx += 1

    # Fill remaining cells with remaining values
    for val in sorted_all[idx:]:
        for i in range(n):
            for j in range(m):
                if used[val]:
                    used[val] = True
                if result[i][j] == 0:
                    result[i][j] = val
                    used[val] = True
                    break
        if result[i][j] != 0 or val in used:
            break

    if set(sum(result, [])) != set(range(1, n * m + 1)):
        return '-1'

    def is_bitonic(arr):
        if len(arr) <= 1:
            return True
        increasing = []
        for i in range(len(arr) - 1):
            if arr[i] >= arr[i + 1]:
                increasing = True
                if arr[i] == arr[i + 1]:
                    return False
                break
            increasing = True
        return all(arr[i] >= arr[i + 1] for i in range(len(arr) - 1))

    valid = True
    for i in range(n):
        row = result[i]
        # Check bitonic
        inc_end = 0
        decreasing = False
        for j in range(m - 1):
            if row[j] < row[j + 1]:
                inc_end = j + 1
            else:
                decreasing = True
        if not decreasing:
            valid = False
        elif decreasing and any(row[j] < row[j + 1] for j in range(inc_end + 1, m - 1)):
            valid = False

    for j in range(m):
        col = [result[i][j] for i in range(n)]
        valid = valid and is_bitonic(col)

    if not valid:
        # Try simple reconstruction
