def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)

    # DFS to build tree structure
    def dfs(u, d):
        visited[u] = True
        depth[u] = d
        for v in adj[u]:
            if not visited[v]:
                parent[v] = u
                dfs(v, d + 1)

    dfs(1, 0)

    # Check for back edges and find long cycle
    for u in range(1, n + 1):
        for v in adj[u]:
            if visited[v] and v != parent[u] and depth[v] < depth[u]:
                if depth[u] - depth[v] + 1 >= target:
                    # Found back edge forming a long cycle
                    cycle = [u]
                    curr = parent[u]
                    while curr != v:
                        cycle.append(curr)
                        curr = parent[curr]
                    cycle.append(v)
                    cycle.reverse()
                    return f"2\n{len(cycle)}\n" + " ".join(map(str, cycle))

    # Construct independent set
    # Use degree ordering to get better independent set
    deg = [len(adj[i]) for i in range(n + 1)]
    nodes_sorted = sorted(range(1, n + 1), key=lambda x: deg[x], reverse=True)

    member = [False] * (n + 1)
    iset = []
    for u in nodes_sorted:
        valid = True
        for v in adj[u]:
            if member[v]:
                valid = False
                break
        if valid:
            iset.append(u)
            member[u] = True
            if len(iset) >= target:
                return f"1\n{len(iset)}\n" + " ".join(map(str, iset))

    # Try DFS order as well
    member = [False] * (n + 1)
    iset = []
    depth_sorted = sorted(range(1, n + 1), key=lambda x: depth[x])
    for u in depth_sorted:
        valid = True
        for v in adj[u]:
            if member[v]:
                valid = False
                break
        if valid:
            iset.append(u)
            member[u] = True
            if len(iset) >= target:
                return f"1\n{len(iset)}\n" + " ".join(map(str, iset))

    # Try reverse DFS order
    member = [False] * (n + 1)
    iset = []
    for u in reversed(range(1, n + 1)):
        valid = True
        for v in adj[u]:
            if member[v]:
                valid = False
                break
        if valid:
            iset.append(u)
            member[u] = True
            if len(iset) >= target:
                return f"1\n{len(iset)}\n" + " ".join(map(str, iset))

    # Fallback - shouldn't happen for valid connected graphs
    return f"1\n{len(iset)}\n" + " ".join(map(str, iset))

