    for i in range(n - m + 1):
        # Track bidirectional character mappings
        mapping = {}
        valid = True

        for j in range(m):
            s_char = s[i + j]
            t_char = t[j]

            if s_char == t_char:
                # Same character, no pair needed
                continue

            # Check if this creates a valid bidirectional mapping
            if s_char in mapping:
                # s_char already has a pair, check consistency
                if mapping[s_char] != t_char:
                    valid = False
                    break
            elif t_char in mapping:
                # t_char already has a pair, check bidirectional consistency
                if mapping[t_char] != s_char:
                    valid = False
                    break
            else:
                # Both new - set up bidirectional mapping
                mapping[s_char] = t_char
                mapping[t_char] = s_char
                # Check bidirectional consistency (mapping[t_char] should be s_char)
                if len([v for v in mapping.values()]) != len(mapping):
                    # Detect if we just caused inconsistency
                    if mapping.get(t_char, None) != s_char:
                        valid = False
                        break

        if valid:
            results.append(i + 1)

