    def parse_int():
        # Parse a number (pos_digit + optional digits)
        start = pos[0]
        if start >= n or expr[start] < '1':  # Must start with pos digit
            return 0
        while pos[0] < n and expr[pos[0]].isdigit():
            pos[0] += 1
        return int(expr[start:pos[0]])

    def parse_term():
        """Parse a term: number, number-range, or number(wrapped expression)"""
        start_pos = pos[0]

        # Must start with a number
        num = parse_int()
        if start_pos == pos[0] or num == 0:
            # No valid number, something is wrong
            return -1

        if pos[0] >= n:
            return num

        # Check what comes after the number
        if rest := expr[pos[0]]:
            c = rest[0]
            pos[0] += 1  # consume the char

            if c == '-':
                # number - number (range)
                num2 = parse_int()
                if num2 == -1:
                    return -1
                return concat_range(num, num2)
            elif c == '(':
                # number (expression)
                pos[0] += 1  # consume '('
                inner = parse_expression()
                if inner == -1 or expr[pos[0]] != ')':
                    return -1
                pos[0] += 1  # consume ')'
                return repeat(num, inner)
            else:
                return num
        else:
            return num

    def power_of_10(k):
        return pow(10, k, MOD)

    def read_until_exception(token):
        """Read until we encounter '(', ')', '-', or '+'"""
        last_pos = pos[0]
        while pos[0] < n:
