            if c == '(' or c == ')' or c == '-' or c == '+':
                return last_pos
            last_pos = pos[0]
            pos[0] += 1
        return last_pos

    def parse_expression():
        """Parse: term | expression '+' term"""
        first = parse_term()
        if first == -1:
            return -1

        last_pos = pos[0]
        while pos[0] < n and expr[pos[0]] == '+':
            pos[0] += 1
            second = parse_term()
            if second == -1:
                return -1
            first = concat_numbers(first, second)

        return first

