    def number_length(num): return len(number_to_str(num))

    def concat_numbers(a, b):
        """Concate a and b numerically: a * 10^len(b) + b mod MOD"""
        len_b = len(number_to_str(b))
        return (a * power_of_10(len_b)) % MOD + b

    def concat_range(l, r):
        """Concatenate all numbers from l to r"""
        if l > r:
            return 0
        if l == r:
            return l

        # Start from l and incrementally append each number
        result = l
        current = l + 1

        while current <= r:
            num_str = number_to_str(current)
            len_current = len(num_str)
            result = (result * power_of_10(len_current)) % MOD
            result = (result + current) % MOD
            current += 1

        return result

    def repeat(count, val):
        """Concatenate val, count times"""
        if count == 0:
            return 0
        result = val
        for _ in range(1, count):
            result = concat_numbers(result, val)
        return result

