from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    roads = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        roads.append((min(a, b), max(a, b)))

    def crosses(r1, r2):
        """Check if two roads intersect (their endpoints alternate around the ring)"""
        a1, b1 = r1
        a2, b2 = r2

        # If they share an endpoint, they don't cross
        if a1 == a2 or b1 == a2 or a1 == b2 or b1 == b2:
            return False

        # Check if exactly one endpoint of r2 is on the clockwise arc from a1 to b1
        def on_arc(start, end, target):
            """Check if target is on the clockwise arc from start to end (not including endpoints)"""
            if start < end:
                return start < target < end
            else:
                return target < end or target > start

        a2_on = on_arc(a1, b1, a2)
        b2_on = on_arc(a1, b1, b2)

        return a2_on != b2_on

    # Build adjacency list for constraint graph
    # Adjacent nodes = roads that cross and must have different assignments
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if crosses(roads[i], roads[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite using BFS coloring
    color = [-1] * m
    possible = True

    for i in range(m):
        if color[i] == -1:
            color[i] = 0
            queue = deque([i])
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break
            if not possible:
                break

    if not possible:
        return "Impossible"

    # 0 -> 'i' (inside), 1 -> 'o' (outside)
    return ''.join('i' if color[i] == 0 else 'o' for i in range(m))

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    MOD = 998244353

    # Generate all valid row permutations and check constraints
    from itertools import permutations

    # Store valid matrices
    valid_matrices = []

    if n == 1:
        valid_matrices.append([[1]])
    elif n == 2:
        for r0 in permutations([1, 2]):
            for r1 in permutations([1, 2]):
                if all(r0[j] != r1[j] for j in range(2)):
                    valid_matrices.append([list(r0), list(r1)])
    elif n == 3:
        all_perms = list(permutations([1, 2, 3]))
        for r0 in all_perms:
            for r1 in all_perms:
                # Vertical constraint
                if any(r0[j] == r1[j] for j in range(3)):
                    continue
                for r2 in all_perms:
                    if all(r1[j] != r2[j] for j in range(3)):
                        valid_matrices.append([list(r0), list(r1), list(r2)])
    else:
        # For larger n (up to 2000), we use the derangement-based formula
        # Number of valid row continuations given previous row = D[n] (derangements)
        # D[n] = (n-1) * (D[n-1] + D[n-2])
        D = [0] * (n + 1)
        D[0] = 1
        D[1] = 0
        for i in range(2, n + 1):
            D[i] = (i - 1) * (D[i - 1] + D[i - 2]) % MOD

        # Method: count contributing positions rather than enumerate
        result = 0

        for i in range(n):  # For each row
            prev_row = matrix[i-1] if i > 0 else [0]*n
            current_row = matrix[i]

            # Track values used in current row prefix
            used_in_row = set()

            for j in range(n):  # For each column
                current_val = current_row[j]

                # Count values smaller than current_val that could be placed here
                for v in range(1, current_val):
                    # Check constraints
                    if v in used_in_row:
                        continue
                    if i > 0 and v == prev_row[j]:
                        continue

                    # v would make current row lexicographically smaller
                    # So this path is counted
                    # Need to count completions

                    # Remaining positions in this row
                    remaining_positions = n - 1 - j

                    # For remaining rows, each must derange from previous
                    remaining_rows = n - 1 - i

                    if remaining_rows > 0:
                        # Number of ways to complete
                        # Simplified: for each remaining row, we have D[n] choices
                        ways = D[n] ** remaining_rows % MOD
                    else:
                        ways = 1

                    result = (result + ways) % MOD

                used_in_row.add(current_val)

        return str(result) + '\n'

    # Sort valid matrices lexicographically and find index
    valid_matrices.sort()

    count = 0
    for vm in valid_matrices:
        if vm == matrix:
            return str(count) + '\n'
        if vm[0] < matrix[0]:
            count += 1
        elif vm[0] > matrix[0]:
            break

    return str(count) + '\n'


