def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    MOD = 998244353

    # Small n: generate all valid matrices
    if n <= 3:
        from itertools import permutations

        valid_matrices = []
        all_perms = list(permutations(range(1, n + 1)))

        for r0 in all_perms:
            for r1 in all_perms:
                vert1 = all(r0[j] != r1[j] for j in range(n))
                if not vert1:
                    continue
                for r2 in all_perms:
                    vert2 = all(r1[j] != r2[j] for j in range(n))
                    if not vert2:
                        continue
                    for r3 in all_perms:
                        vert3 = all(r2[j] != r3[j] for j in range(n))
                        if not vert3:
                            continue
                        for r4 in all_perms:
                            vert4 = all(r3[j] != r4[j] for j in range(n))
                            if not vert4:
                                continue

                            current = [list(r0), list(r1)]
                            if n == 3:
                                current.append(list(r2))
                                mat = tuple(tuple(r) for r in current)

                                if mat < tuple(tuple(r) for r in matrix):
                                    count = 1
                                elif mat > tuple(tuple(r) for r in matrix):
                                    break
                                else:
                                    return '0\n'

        # Sort and find index
        pass

    # Use direct counting approach
    result = 0

    # Precompute derangements
    D = [1, 0]
    for i in range(2, n + 1):
        D.append((i - 1) * (D[i-1] + D[i-2]) % MOD)

    for i in range(n):
        prev_row = matrix[i-1] if i > 0 else None
        for j in range(n):
            target = matrix[i][j]
            for v in range(1, target):
                # Check if v is valid at (i,j)
                valid = True
                if v in set(matrix[r][j] for r in range(min(i, n))): pass  # Already tracked
                if i > 0 and v == prev_row[j]:
                    valid = False
                if valid:
                    result = (result + pow(D[n], n - i - 1, MOD)) % MOD

    return str(result % MOD) + '\n'

MOD = 10**9 + 7

def mat_mult(A, B):
    """Multiply two 3x3 matrices modulo MOD"""
    C = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

