def solution(input_str):
    n, k = map(int, input_str.split())

    if k == 1:
        return str(n % 998244353)

    MOD = 998244353

    # dp[v] = number of valid chains of current length ending at value v
    # Initially for chains of length 1, every value v can end a chain
    dp = [1] * (n + 1)

    # Process transitions from chains of length j to length j+1
    for j in range(k - 1):
        new_dp = [0] * (n + 1)

        # For each value v, add its contribution to all multiples m >= 2*v
        for v in range(1, n + 1):
            if dp[v] == 0:
                continue
            count = dp[v]
            # Update all multiples
            for m in range(2 * v, n + 1, v):
                new_dp[m] = (new_dp[m] + count) % MOD

        dp = new_dp

    # Sum all chains of length k
    result = sum(dp[1:]) % MOD
    return str(result)


